 * Instant-runoff counting over a parsed election.
 */

/**
 * Picks which of the tied-for-fewest candidates to eliminate, following the
 * rule: compare their vote counts round by round from the first round; at
 * the first round where they differ, keep only those with the fewest votes
 * there and restart the comparison from the first round; if no round ever
 * separates them, eliminate whichever name sorts last by code point.
 */
function breakTie(tied, history) {
  let survivors = tied
  for (;;) {
    let narrowed = null
    for (const counts of history) {
      const values = survivors.map((name) => counts.get(name))
      const min = Math.min(...values)
      if (values.some((value) => value !== min)) {
        narrowed = survivors.filter((name) => counts.get(name) === min)
        break
      }
    }
    if (narrowed === null) break
    survivors = narrowed
    if (survivors.length === 1) break
  }
  if (survivors.length === 1) return survivors[0]
  return survivors.slice().sort().pop()
}

/**
 * Counts the election round by round. Returns `{ rounds, winner }`, where
 * `rounds` is a list of `{ counts, exhausted, eliminated }` (`counts` a
 * `Map<name, votes>` of that round's continuing candidates in declaration
 * order, `eliminated` the name removed after the round or `null`) and
 * `winner` is the winning name or `null`.
 */
export function countElection(election) {
  let continuing = election.candidates.slice()
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map(continuing.map((name) => [name, 0]))
    let exhausted = 0
    for (const ballot of election.ballots) {
      const choice = ballot.names.find((name) => counts.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }
    history.push(counts)

    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const majority = continuing.find((name) => counts.get(name) * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const min = Math.min(...continuing.map((name) => counts.get(name)))
    const tied = continuing.filter((name) => counts.get(name) === min)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    rounds.push({ counts, exhausted, eliminated })
    continuing = continuing.filter((name) => name !== eliminated)
  }

  return { rounds, winner }
}
"}

