{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-ruJhDe/src/format.js","content":"/**
 * Rendering of a counted election as the `rounds` or `tally` output.
 */

function formatRoundLine(roundNumber, round) {
  const entries = [...round.counts.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

function formatOutcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}

/** Renders the full `rounds` output. */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    lines.push(formatRoundLine(index + 1, round))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(formatOutcome(result.winner))
  return lines.map((line) => line + '\n').join('')
}

/** Renders the `tally` output. */
export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${formatOutcome(result.winner)}\n`
}
"}

