import { parseElection, ParseError } from './parse.js'
import { countElection } from './count.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const text = readStdin()

  let election
  try {
    election = parseElection(text)
  } catch (error) {
    if (error instanceof ParseError) {
      process.stderr.write(error.message + '\n')
      process.exit(2)
    }
    throw error
  }

  const result = countElection(election)
  process.stdout.write(mode === 'rounds' ? formatRounds(result) : formatTally(result))
}

